{
  "title": "The Glass Diver's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescuers arrive at the ruined city gates.",
      "visual_description": "Crumbling stone gates wrapped in rusted iron, with old royal banners torn and hanging from the archway. The glass diver and Mara the Cartographer stand before it, the diver's helmet reflecting the cracked stone.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unfolds a map, revealing a cursed tower.",
      "visual_description": "Mara the Cartographer unrolls a stained parchment map on a fallen pillar. The map glows faintly, showing a spiral tower drawn in red ink. The glass diver peers over her shoulder.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp warns of a trap ahead.",
      "visual_description": "The Oracle Lamp hovers at waist height, its single eye flickering. The flame casts shadows of bars across the ground, as if warning of a cage. Mara pauses, hand on her compass.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "They find the Sleeping Tax Collector slumped against a fountain.",
      "visual_description": "A dry fountain in a square, the Sleeping Tax Collector dozes with a ledger book as a pillow. Stamped papers are stuck to his sleeves. A wind scatters loose leaves around him.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scampers ahead to scout the main street.",
      "visual_description": "The Tin Fox, key-wind tail spinning, races down a cobblestone street lined with collapsed stalls. Its blue glass eyes scan the shadows. The glass diver watches from a doorway.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Armored patrols march past a shattered fountain.",
      "visual_description": "Three figures in dented armor clank across the square, their visors lowered. The Tin Fox freezes behind a broken pillar, its key-wind tail tucked still.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Mara traces a secret path through the ruins.",
      "visual_description": "Mara the Cartographer runs her ink-stained finger along the map, then points to a narrow alley choked with debris. The Oracle Lamp hovers beside her, casting a dim pool of light.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver swims through a mirror in a shattered shop.",
      "visual_description": "Inside a ruined shop, the glass diver presses his helmet against a cracked standing mirror. The glass ripples, and he steps through, emerging in a dusty courtyard on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector is nudged awake by the Tin Fox.",
      "visual_description": "The Tin Fox nudges the Sleeping Tax Collector's hand with its metal snout. The collector stirs, blinking, a paper stuck to his cheek. Mara sighs impatiently nearby.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The Oracle Lamp reveals a magic door hidden behind a tapestry.",
      "visual_description": "The Oracle Lamp's flame brightens, illuminating a faded tapestry on a wall. Behind it, a stone door pulses with faint runes. The glass diver touches the door, and it hums.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Mara deciphers the riddle on the magic door.",
      "visual_description": "Mara the Cartographer studies the runes, muttering, her compass needle spinning. The door's runes shift position. The glass diver waits, hand on his helmet.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The door opens to a spiral staircase leading up a cursed tower.",
      "visual_description": "The magic door swings inward, revealing a narrow spiral staircase of black stone. Dust motes drift in the air. The Oracle Lamp floats first, casting dancing shadows.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Frightened townspeople huddle in a chapel, whispering rumors.",
      "visual_description": "Through a broken window, the glass diver sees a small chapel where a group of figures in tattered clothes huddle together, whispering. One points upward toward the tower.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The Tin Fox reports back, key-wind tail wagging.",
      "visual_description": "The Tin Fox returns to the group, its blue glass eyes bright. It taps a metal paw on the map, indicating a route. Mara nods, folding the map.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The Sleeping Tax Collector stamps a useless permit.",
      "visual_description": "The Sleeping Tax Collector, still groggy, pulls a stamp from his coat and stamps the air, mumbling about clearance. The others ignore him and move on.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the bridge, but patrols block the far end.",
      "visual_description": "A narrow stone bridge spans a chasm. On the far side, armored figures stand silhouetted against the setting sun. The bridge's ropes creak. The glass diver peers down into the mist.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver creates a distraction by reflecting light.",
      "visual_description": "The glass diver tilts his helmet, catching the last sunlight and flashing it into the patrols' eyes. They shield their faces, stumbling. The group dashes onto the bridge.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They escape across the bridge as it crumbles behind them.",
      "visual_description": "The group runs across the bridge, planks splintering underfoot. The far side crumbles into the chasm. They leap to safety as the bridge collapses. The Oracle Lamp's flame gutters, then steadies.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ],
  "gate_token": "nvSJ4tS4d9Lu2cA1aVPgPw"
}

